const iconFor = (platform: string) => {
  const key = platform.toLowerCase().replace(/[^a-z0-9]/g, '')
  return BRAND_ICONS[key] ? key : FALLBACK_ICON
}

const props = defineProps<{ platform: string }>()

// A brand mark is filled; the fallback is drawn, matching what the header has always produced.
const key = computed(() => iconFor(props.platform))
const isBrand = computed(() => key.value !== FALLBACK_ICON)
