<template>
  <!-- A single root <svg> on purpose. If the brand and fallback marks were two sibling elements
       behind v-if/v-else, the component would have two roots and Vue would stop passing the
       caller's `class` through — the sizing would vanish with no error anywhere. -->
  <svg
    xmlns="http://www.w3.org/2000/svg"
    viewBox="0 0 24 24"
    :fill="isBrand ? 'currentColor' : 'none'"
    :stroke="isBrand ? 'none' : 'currentColor'"
    stroke-width="2"
    stroke-linecap="round"
    stroke-linejoin="round"
    class="h-4 w-4"
    aria-hidden="true"
  >
    <path v-if="isBrand" :d="BRAND_ICONS[key]" />
    <template v-else>
      <circle cx="12" cy="12" r="10" />
      <path d="M12 2a14.5 14.5 0 0 0 0 20 14.5 14.5 0 0 0 0-20" />
      <path d="M2 12h20" />
    </template>
  </svg>
</template>
